    ld hl, sp+$1a
    ld a, [hl]
    and $0c
    ld c, a
    sub $0c
    jp z, CreateName_B5_caseMixSetLfn

    ld hl, sp+$1a
    ld a, [hl]
    and $03
    ld b, a
    sub $03
    jp nz, CreateName_B5_caseMixOk

    jr CreateName_B5_caseMixSetLfn

CreateName_B5_caseMixOk::
    jp CreateName_B5_storeNtFlags


CreateName_B5_caseMixSetLfn::
    ld hl, sp+$19
    ld a, [hl]
