; [ezgb]
; Validate_B5(obj): FatFs validate. Push frame; reject null obj/fs, fs_type==0, or id mismatch → Validate_B5_invalid E=$09.
; obj->id vs fs->id mismatch → Validate_B5_idMismatch→Validate_B5_invalid; Validate_B5_diskStatus DiskStatus&$01 set → Validate_B5_invalid else Validate_B5_ok E=0.
; Validate_B5_epilogue add sp,$04 ret E.

Validate_B5::
    push af
    push af
    ld hl, sp+$06
    ld a, [hl+]
    or [hl]
    jp z, Validate_B5_invalid

    dec hl
    ld e, [hl]
    inc hl
    ld d, [hl]
    ld a, [de]
    ld c, a
    inc de
    ld a, [de]
    ld b, a
    or c
    jp z, Validate_B5_invalid

    dec hl
    ld e, [hl]
    inc hl
    ld d, [hl]
    ld a, [de]
    ld c, a
    inc de
    ld a, [de]
    ld b, a
    ld a, [bc]
    or a
    jp z, Validate_B5_invalid

    dec hl
    ld e, [hl]
    inc hl
    ld d, [hl]
    ld a, [de]
    ld hl, sp+$02
    ld [hl+], a
    inc de
    ld a, [de]
    ld [hl-], a
    ld e, [hl]
    inc hl
    ld d, [hl]
    ld hl, $0006
    add hl, de
    ld c, l
    ld b, h
    ld e, c
    ld d, b
    ld a, [de]
    ld hl, sp+$00
    ld [hl+], a
    inc de
    ld a, [de]
    ld [hl], a
    ld hl, sp+$06
    ld c, [hl]
    inc hl
    ld b, [hl]
    inc bc
    inc bc
    ld e, c
    ld d, b
    ld a, [de]
    ld c, a
    inc de
    ld a, [de]
    ld b, a
    ld hl, sp+$00
    ld a, [hl]
    sub c
    jp nz, Validate_B5_idMismatch

    inc hl
    ld a, [hl]
    sub b
    jp nz, Validate_B5_idMismatch

    jr Validate_B5_diskStatus

Validate_B5_idMismatch::
    jp Validate_B5_invalid


Validate_B5_diskStatus::
    ld hl, sp+$02
    ld c, [hl]
    inc hl
    ld b, [hl]
    inc bc
    ld a, [bc]
    ld c, a
    push af
    inc sp
    call DiskStatus
    add sp, $01
    ld c, e
    ld a, c
    and $01
    jr nz, Validate_B5_invalid

    jp Validate_B5_ok


Validate_B5_invalid::
    ld e, $09
    jp Validate_B5_epilogue


Validate_B5_ok::
    ld e, $00

Validate_B5_epilogue::
    add sp, $04
    ret


; [ezgb]
; Mount_B5(fs, path, opt): FatFs f_mount. GetLdNumber_B5 bit7→E=$0b Mount_B5_epilogue else Mount_B5_afterLdOk.
; Mount_B5_afterLdOk: FatFs[vol]@$C5A5; if cfs set fs_type=0; Mount_B5_afterUnreg: if fs null→Mount_B5_registerFs else clear *fs.
; Mount_B5_registerFs: FatFs[vol]=fs; fs null or opt!=1 → Mount_B5_retOk E=0; else Mount_B5_findVolume FindVolume_B5; Mount_B5_epilogue epilogue.

Mount_B5::
    push af
    push af
    ld hl, sp+$0c
    ld a, [hl+]
    ld e, [hl]
    ld hl, sp+$02
    ld [hl+], a
    ld [hl], e
    ld hl, sp+$02
    ld c, l
    ld b, h
    push bc
    call GetLdNumber_B5
    add sp, $02
    ld b, d
    ld c, e
    ld a, b
    bit 7, a
    jp z, Mount_B5_afterLdOk

    ld e, $0b
    jp Mount_B5_epilogue


Mount_B5_afterLdOk::
    sla c
    rl b
    ld hl, $c5a5
    add hl, bc
    ld a, l
    ld d, h
    ld hl, sp+$00
    ld [hl+], a
    ld [hl], d
    ld e, a
    ld a, [de]
    ld c, a
    inc de
    ld a, [de]
    ld b, a
    or c
    jp z, Mount_B5_afterUnreg

    ld a, $00
    ld [bc], a

