    ld hl, sp+$0a
    ld a, [hl+]
    or [hl]
    jp z, Mount_B5_registerFs

    dec hl
    ld c, [hl]
    inc hl
    ld b, [hl]
    ld a, $00
    ld [bc], a

Mount_B5_registerFs::
