    ld e, [hl]
    inc hl
    ld d, [hl]
    ld hl, sp+$0a
    ld a, [hl]
    ld [de], a
    inc de
    inc hl
    ld a, [hl]
    ld [de], a
    dec hl
    ld a, [hl+]
    or [hl]
    jp z, Mount_B5_retOk

    ld hl, sp+$0e
    ld a, [hl]
    sub $01
    jp z, Mount_B5_findVolume

Mount_B5_retOk::
    ld e, $00
    jp Mount_B5_epilogue


Mount_B5_findVolume::
    ld hl, sp+$0c
    ld a, l
    ld d, h
    ld hl, sp+$00
