    ld hl, sp+$39
    ld a, [hl]
    ld hl, sp+$03
    sub [hl]
    jp nz, Getcwd_B5_dirNextChild

    ld hl, sp+$3a
    ld a, [hl]
    ld hl, sp+$04
    sub [hl]
    jp nz, Getcwd_B5_dirNextChild

    ld hl, sp+$3b
    ld a, [hl]
    ld hl, sp+$05
    sub [hl]
    jp z, Getcwd_B5_afterFindChild

Getcwd_B5_dirNextChild::
    ld hl, sp+$40
    ld c, l
    ld b, h
    ld hl, $0000
    push hl
    push bc
    call DirNext_B5
    add sp, $04
    ld c, e
    ld hl, sp+$5a
    ld [hl], c
    xor a
    or [hl]
    jp z, Getcwd_B5_findChildEntry

Getcwd_B5_afterFindChild::
    ld hl, sp+$5a
    ld a, [hl]
    sub $04
    jp nz, Getcwd_B5_findChildOk

    jr Getcwd_B5_setIntErr

Getcwd_B5_findChildOk::
    jp Getcwd_B5_checkRes


Getcwd_B5_setIntErr::
