    ld hl, sp+$1c
    ld a, l
    ld d, h
    ld hl, sp+$00
    ld [hl+], a
    ld [hl], d
    dec hl
    ld e, [hl]
    inc hl
    ld d, [hl]
    ld hl, $0016
    add hl, de
    ld c, l
    ld b, h
    ld e, c
    ld d, b
    ld hl, sp+$61
    ld a, [hl]
    ld [de], a
    inc de
    inc hl
    ld a, [hl]
    ld [de], a
    ld hl, sp+$00
    ld e, [hl]
    inc hl
    ld d, [hl]
    ld hl, $0018
    add hl, de
    ld c, l
    ld b, h
    ld e, c
    ld d, b
    ld hl, sp+$3e
    ld a, [hl]
    ld [de], a
    inc de
    inc hl
    ld a, [hl]
    ld [de], a
    ld hl, sp+$40
    ld c, l
    ld b, h
    ld hl, sp+$00
    ld a, [hl+]
    ld h, [hl]
    ld l, a
    push hl
    push bc
    call GetFileInfo_B5
    add sp, $04
    ld hl, sp+$06
    ld a, [hl+]
    ld e, [hl]
    ld hl, sp+$36
    ld [hl+], a
    ld [hl], e
    ld hl, sp+$61
    ld a, [hl+]
    ld e, [hl]
    ld hl, sp+$00
    ld [hl+], a
    ld [hl], e
    dec hl
    ld e, [hl]
    inc hl
    ld d, [hl]
    ld a, [de]
    or a
    jp z, Getcwd_B5_initNameLen

    dec hl
    ld a, [hl+]
    ld e, [hl]
    ld hl, sp+$36
    ld [hl+], a
    ld [hl], e

Getcwd_B5_initNameLen::
    ld hl, sp+$3c
    ld [hl], $00
    inc hl
    ld [hl], $00

Getcwd_B5_nameLenLoop::
    ld hl, sp+$36
    ld e, [hl]
    inc hl
    ld d, [hl]
    ld hl, sp+$3c
    ld a, [hl+]
    ld h, [hl]
    ld l, a
    add hl, de
    ld c, l
    ld b, h
    ld a, [bc]
    or a
    jp z, Getcwd_B5_checkBufSpace

    ld hl, sp+$3c
    inc [hl]
    jr nz, Getcwd_B5_nameLenCont

    inc hl
    inc [hl]

Getcwd_B5_nameLenCont::
    jp Getcwd_B5_nameLenLoop


Getcwd_B5_checkBufSpace::
    ld hl, sp+$3c
    ld e, [hl]
    inc hl
    ld d, [hl]
    ld hl, $0003
    add hl, de
    ld c, l
    ld b, h
    ld hl, sp+$3e
    ld a, [hl]
    sub c
    inc hl
    ld a, [hl]
    sbc b
    jp nc, Getcwd_B5_stackName

    ld hl, sp+$5a
    ld [hl], $11
    jp Getcwd_B5_afterWalk


Getcwd_B5_stackName::
    ld hl, sp+$3e
    ld a, [hl+]
    ld e, [hl]
    ld hl, sp+$02
    ld [hl+], a
    ld [hl], e

Getcwd_B5_stackNameLoop::
    ld hl, sp+$3c
    ld a, [hl+]
    or [hl]
    jp z, Getcwd_B5_stackSlash

    ld hl, sp+$02
    ld e, [hl]
    inc hl
    ld d, [hl]
    dec de
    dec hl
    ld [hl], e
    inc hl
    ld [hl], d
    ld hl, sp+$00
    ld e, [hl]
    inc hl
    ld d, [hl]
    inc hl
    ld a, [hl+]
    ld h, [hl]
    ld l, a
    add hl, de
    ld a, l
    ld d, h
    ld hl, sp+$0e
    ld [hl+], a
    ld [hl], d
    ld hl, sp+$3c
    ld e, [hl]
    inc hl
    ld d, [hl]
    dec de
    dec hl
    ld [hl], e
    inc hl
    ld [hl], d
    ld hl, sp+$36
    ld e, [hl]
    inc hl
    ld d, [hl]
    ld hl, sp+$3c
    ld a, [hl+]
    ld h, [hl]
    ld l, a
    add hl, de
    ld c, l
    ld b, h
    ld a, [bc]
    ld hl, sp+$0e
    ld e, [hl]
