Getcwd_B5_stackSlash::
    ld hl, sp+$02
    ld e, [hl]
    inc hl
    ld d, [hl]
    ld hl, $0001
    ld a, e
    sub l
    ld e, a
    ld a, d
    sbc h
    ld hl, sp+$3f
    ld [hl-], a
    ld [hl], e
    ld hl, sp+$00
    ld e, [hl]
