    ld hl, sp+$00
    ld [hl+], a
    ld [hl], e

Getcwd_B5_copyPathLoop::
    ld hl, sp+$02
    ld c, [hl]
    inc hl
    ld b, [hl]
    dec hl
    inc [hl]
    jr nz, Getcwd_B5_copyPathBody

    inc hl
    inc [hl]

Getcwd_B5_copyPathBody::
    ld hl, sp+$61
    ld a, [hl+]
    ld h, [hl]
    ld l, a
    add hl, bc
    ld c, l
    ld b, h
    ld a, [bc]
    ld hl, sp+$00
    ld e, [hl]
    inc hl
    ld d, [hl]
    ld [de], a
    dec hl
    inc [hl]
