; [ezgb]
; Opendir_B5(dp, path): FatFs f_opendir. Frame -$19; sp+$18 holds E.
; dp null → E=$09 Opendir_B5_epilogue; Opendir_B5_afterNullCheck FindVolume_B5 err → Opendir_B5_cleanup.
; Init dp; FollowPath_B5 err → Opendir_B5_afterDirSdi; cluster zero → Opendir_B5_dirSdi0.
; ATTR_DIR → Opendir_B5_loadDirClust LdClust_B5 into dp+$06 → Opendir_B5_dirSdi0 else Opendir_B5_notDir E=$05.
; Opendir_B5_dirSdi0: err → Opendir_B5_afterDirSdi else DirSdi_B5(0); E==$04 → Opendir_B5_noFileAsDenied E=$05 else Opendir_B5_dirSdiOk→Opendir_B5_cleanup.
; Opendir_B5_cleanup: err clear dp fs ptr; Opendir_B5_loadResult/Opendir_B5_epilogue add sp,$19 ret E.

Opendir_B5::
    add sp, -$19
    ld hl, sp+$1f
    ld a, [hl+]
    or [hl]
    jp nz, Opendir_B5_afterNullCheck

    ld e, $09
    jp Opendir_B5_epilogue


Opendir_B5_afterNullCheck::
    ld hl, sp+$21
    ld a, l
    ld d, h
    ld hl, sp+$08
    ld [hl+], a
    ld [hl], d
    ld hl, sp+$16
    ld c, l
    ld b, h
    ld a, $00
    push af
    inc sp
    ld hl, sp+$09
    ld a, [hl+]
    ld h, [hl]
    ld l, a
    push hl
    push bc
    call FindVolume_B5
    add sp, $05
    ld c, e
    ld hl, sp+$18
    ld [hl], c
    xor a
    or [hl]
    jp nz, Opendir_B5_cleanup

    ld hl, sp+$1f
    ld c, [hl]
    inc hl
    ld b, [hl]
    ld e, c
    ld d, b
    ld hl, sp+$16
    ld a, [hl]
    ld [de], a
    inc de
    inc hl
    ld a, [hl]
    ld [de], a
    ld hl, $0014
    add hl, bc
    ld a, l
    ld d, h
    ld hl, sp+$06
    ld [hl+], a
    ld [hl], d
    ld hl, sp+$0a
    ld a, l
    ld d, h
    ld hl, sp+$04
    ld [hl+], a
    ld [hl], d
    inc hl
    ld e, [hl]
    inc hl
    ld d, [hl]
    ld hl, sp+$04
    ld a, [hl]
    ld [de], a
    inc de
    inc hl
    ld a, [hl]
    ld [de], a
    ld hl, $0016
    add hl, bc
    ld a, l
    ld d, h
    ld hl, sp+$04
    ld [hl+], a
    ld [hl], d
    dec hl
    ld e, [hl]
    inc hl
    ld d, [hl]
    ld a, $a9
    ld [de], a
    inc de
    ld a, $c5
    ld [de], a
    ld hl, sp+$21
    ld a, [hl+]
    ld h, [hl]
    ld l, a
    push hl
    push bc
    call FollowPath_B5
    add sp, $04
    ld b, e
    ld hl, sp+$18
    ld [hl], b
    xor a
    or [hl]
    jp nz, Opendir_B5_afterDirSdi

    ld hl, sp+$1f
    ld a, [hl+]
    ld e, [hl]
    ld hl, sp+$04
    ld [hl+], a
    ld [hl], e
    dec hl
    ld e, [hl]
    inc hl
    ld d, [hl]
    ld hl, $0012
    add hl, de
    ld c, l
    ld b, h
    ld e, c
    ld d, b
    ld a, [de]
    ld hl, sp+$06
    ld [hl+], a
    inc de
    ld a, [de]
    ld [hl-], a
    ld a, [hl+]
    or [hl]
    jp z, Opendir_B5_dirSdi0

    dec hl
    ld e, [hl]
    inc hl
    ld d, [hl]
    ld hl, $000b
    add hl, de
    ld c, l
    ld b, h
    ld a, [bc]
    ld c, a
    and $10
    jr nz, Opendir_B5_loadDirClust

    jp Opendir_B5_notDir


Opendir_B5_loadDirClust::
    ld hl, sp+$04
    ld e, [hl]
    inc hl
    ld d, [hl]
    ld hl, $0006
    add hl, de
    ld c, l
    ld b, h
    push bc
    ld hl, sp+$08
    ld a, [hl+]
    ld h, [hl]
    ld l, a
    push hl
    ld hl, sp+$1a
    ld a, [hl+]
    ld h, [hl]
    ld l, a
    push hl
    call LdClust_B5
    add sp, $04
    push hl
    ld hl, sp+$04
    ld [hl], e
    inc hl
    ld [hl], d
    pop de
    inc hl
    ld [hl], e
    inc hl
    ld [hl], d
    pop bc
    ld e, c
    ld d, b
    ld hl, sp+$00
    ld a, [hl]
    ld [de], a
    inc de
    inc hl
    ld a, [hl]
    ld [de], a
    inc de
    inc hl
    ld a, [hl]
    ld [de], a
    inc de
    inc hl
    ld a, [hl]
    ld [de], a
    jp Opendir_B5_dirSdi0


Opendir_B5_notDir::
    ld hl, sp+$18
    ld [hl], $05

Opendir_B5_dirSdi0::
    xor a
    ld hl, sp+$18
    or [hl]
    jp nz, Opendir_B5_afterDirSdi

    ld hl, sp+$04
    ld e, [hl]
    inc hl
    ld d, [hl]
    ld hl, $0002
    add hl, de
    ld a, l
    ld d, h
    ld hl, sp+$00
    ld [hl+], a
    ld [hl], d
    ld hl, sp+$16
    ld c, [hl]
    inc hl
    ld b, [hl]
    ld hl, $0006
    add hl, bc
    ld c, l
    ld b, h
    ld e, c
    ld d, b
    ld a, [de]
    ld c, a
    inc de
    ld a, [de]
    ld b, a
    ld hl, sp+$00
    ld e, [hl]
    inc hl
    ld d, [hl]
    ld a, c
    ld [de], a
    inc de
    ld a, b
    ld [de], a
    ld hl, $0000
    push hl
    ld hl, sp+$06
    ld a, [hl+]
    ld h, [hl]
    ld l, a
    push hl
    call DirSdi_B5
    add sp, $04
    ld c, e
    ld hl, sp+$18
    ld [hl], c

Opendir_B5_afterDirSdi::
    ld hl, sp+$18
    ld a, [hl]
    sub $04
    jp nz, Opendir_B5_dirSdiOk

    jr Opendir_B5_noFileAsDenied

Opendir_B5_dirSdiOk::
    jp Opendir_B5_cleanup


Opendir_B5_noFileAsDenied::
    ld hl, sp+$18
    ld [hl], $05

Opendir_B5_cleanup::
    xor a
    ld hl, sp+$18
    or [hl]
    jp z, Opendir_B5_loadResult

    ld hl, sp+$1f
    ld c, [hl]
    inc hl
    ld b, [hl]
    ld e, c
    ld d, b
    ld a, $00
    ld [de], a
    inc de
    ld a, $00
    ld [de], a

Opendir_B5_loadResult::
    ld hl, sp+$18
    ld e, [hl]

Opendir_B5_epilogue::
    add sp, $19
    ret


; [ezgb]
; Closedir_B5(dp): FatFs f_closedir. Validate_B5; ok clear dp fs ptr (2 bytes); Closedir_B5_epilogue ret E.

Closedir_B5::
    dec sp
    ld hl, sp+$07
    ld c, [hl]
    inc hl
    ld b, [hl]
    push bc
    call Validate_B5
    add sp, $02
    ld c, e
    ld hl, sp+$00
    ld [hl], c
    xor a
    or [hl]
    jp nz, Closedir_B5_epilogue

    ld hl, sp+$07
    ld c, [hl]
    inc hl
    ld b, [hl]
    ld e, c
    ld d, b
    ld a, $00
    ld [de], a
    inc de
    ld a, $00
    ld [de], a

Closedir_B5_epilogue::
    ld hl, sp+$00
    ld e, [hl]
    add sp, $01
    ret


; [ezgb]
; Readdir_B5(dp, fno): FatFs f_readdir. Frame -$10; Validate_B5 fail → Readdir_B5_epilogue.
; fno null → DirSdi_B5(0) rewind → Readdir_B5_epilogue; Readdir_B5_dirRead: stamp dp, DirRead_B5.
; DirRead E==$04 (NO_FILE) → Readdir_B5_eofClearClust zero cluster else Readdir_B5_afterDirRead→Readdir_B5_getInfoNext with E.
; Readdir_B5_getInfoNext: E=0 → GetFileInfo_B5 + DirNext_B5(0); E==$04 → Readdir_B5_eofClearClust2 zero cluster else Readdir_B5_afterDirNext→Readdir_B5_epilogue.
; Readdir_B5_epilogue add sp,$10 ret E.

Readdir_B5::
    add sp, -$10
    ld hl, sp+$16
    ld c, [hl]
    inc hl
    ld b, [hl]
    push bc
    call Validate_B5
    add sp, $02
    ld c, e
    xor a
    or c
    jp nz, Readdir_B5_epilogue

    ld hl, sp+$18
    ld a, [hl+]
    or [hl]
    jp nz, Readdir_B5_dirRead

    ld hl, $0000
    push hl
    ld hl, sp+$18
    ld a, [hl+]
    ld h, [hl]
    ld l, a
    push hl
    call DirSdi_B5
    add sp, $04
    ld b, e
    ld c, b
    jp Readdir_B5_epilogue


Readdir_B5_dirRead::
    ld hl, sp+$16
    ld c, [hl]
    inc hl
    ld b, [hl]
    ld hl, $0014
    add hl, bc
    ld a, l
    ld d, h
    ld hl, sp+$02
    ld [hl+], a
    ld [hl], d
    ld hl, sp+$04
    ld a, l
    ld d, h
