    ld e, [hl]
    inc hl
    ld d, [hl]
    ld hl, sp+$00
    ld a, [hl]
    ld [de], a
    inc de
    inc hl
    ld a, [hl]
    ld [de], a
    ld hl, $0016
    add hl, bc
    ld a, l
    ld d, h
    ld hl, sp+$00
    ld [hl+], a
    ld [hl], d
    dec hl
    ld e, [hl]
    inc hl
    ld d, [hl]
    ld a, $a9
    ld [de], a
    inc de
    ld a, $c5
    ld [de], a
    ld hl, $0000
    push hl
    push bc
    call DirRead_B5
    add sp, $04
    ld b, e
    ld c, b
    ld a, c
    sub $04
    jp nz, Readdir_B5_afterDirRead

    jr Readdir_B5_eofClearClust

Readdir_B5_afterDirRead::
    jp Readdir_B5_getInfoNext


Readdir_B5_eofClearClust::
    ld hl, sp+$16
    ld a, [hl+]
    ld e, [hl]
    ld hl, sp+$00
    ld [hl+], a
    ld [hl], e
    dec hl
    ld e, [hl]
    inc hl
    ld d, [hl]
    ld hl, $000e
    add hl, de
    ld a, l
    ld d, h
    ld hl, sp+$00
    ld [hl+], a
    ld [hl], d
    dec hl
    ld e, [hl]
    inc hl
    ld d, [hl]
    ld a, $00
    ld [de], a
    inc de
    ld a, $00
    ld [de], a
    inc de
    ld a, $00
    ld [de], a
    inc de
    ld a, $00
    ld [de], a
    ld c, $00

Readdir_B5_getInfoNext::
    xor a
    or c
    jp nz, Readdir_B5_epilogue

    ld hl, sp+$18
    ld a, [hl+]
    ld h, [hl]
    ld l, a
    push hl
    ld hl, sp+$18
    ld a, [hl+]
    ld h, [hl]
    ld l, a
